    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_D(PARAMS_SEED);

    KeyDiffuse_B_A_B(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BETELGEUSE_KEY_A_B_IceLaneA, BETELGEUSE_KEY_A_B_IceLaneB, BETELGEUSE_KEY_A_B_IceLaneC, BETELGEUSE_KEY_A_B_IceLaneD, &(pWorkSpace->mKeyBoxA[1U][0]));

    // Key flow — A / C

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BETELGEUSE_KEY_A_C_IceLaneA, BETELGEUSE_KEY_A_C_IceLaneB, BETELGEUSE_KEY_A_C_IceLaneC, BETELGEUSE_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

    // Key flow — A / D

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_D_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_D_B(PARAMS_SEED);

    KeyDiffuse_A_A_D(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_D_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BETELGEUSE_KEY_A_D_IceLaneA, BETELGEUSE_KEY_A_D_IceLaneB, BETELGEUSE_KEY_A_D_IceLaneC, BETELGEUSE_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
